/* Headerless (raw) audio, and the sample coding used by nearly every other
 * format module.
 *
 * Original work, written from the observed behaviour of the reference program.
 *
 * The diagnostics issued from here must appear to come from the `raw'
 * subsystem (the reference prints e.g. "WARN raw: `f.s16': sample rate not
 * specified; trying 8kHz"), so the message subsystem is set explicitly rather
 * than being taken from this file's name.
 */
#include "sox_i.h"

#define RAW_SUBSYSTEM "raw.c"
#define raw_warn   (sox_globals.subsystem = RAW_SUBSYSTEM), lsx_warn_impl
#define raw_report (sox_globals.subsystem = RAW_SUBSYSTEM), lsx_report_impl

/*--------------------------- Encoding dispatch ----------------------------*/

typedef enum {
  raw_bad, raw_s8, raw_u8, raw_ulaw, raw_alaw,
  raw_s16, raw_u16, raw_s24, raw_u24, raw_s32, raw_u32, raw_f32, raw_f64
} raw_kind_t;

static raw_kind_t raw_kind(sox_format_t ft)
{
  unsigned bits = ft->encoding.bits_per_sample;

  switch (ft->encoding.encoding) {
    case SOX_ENCODING_SIGN2:
      return bits == 8 ? raw_s8 : bits == 16 ? raw_s16 :
             bits == 24 ? raw_s24 : bits == 32 ? raw_s32 : raw_bad;
    case SOX_ENCODING_UNSIGNED:
      return bits == 8 ? raw_u8 : bits == 16 ? raw_u16 :
             bits == 24 ? raw_u24 : bits == 32 ? raw_u32 : raw_bad;
    case SOX_ENCODING_ULAW:
      return bits == 8 ? raw_ulaw : raw_bad;
    case SOX_ENCODING_ALAW:
      return bits == 8 ? raw_alaw : raw_bad;
    case SOX_ENCODING_FLOAT:
      return bits == 32 ? raw_f32 : bits == 64 ? raw_f64 : raw_bad;
    default:
      return raw_bad;
  }
}

static void raw_bad_size(sox_format_t ft)
{
  ft->sox_errno = SOX_EFMT;
  strncpy(ft->sox_errstr, "this handler does not support this data size",
          sizeof(ft->sox_errstr) - 1);
  ft->sox_errstr[sizeof(ft->sox_errstr) - 1] = '\0';
}

/*----------------- Bit and nibble reversal (8-bit codings) -----------------*/

/* The reference applies these only to codings whose unit is a single byte
 * (or a nibble); 16-bit and wider samples are left alone even when
 * `Reverse Bits' is reported as `yes'. */

static uint8_t raw_bitrev(uint8_t b)
{
  b = (uint8_t)((b >> 4) | (b << 4));
  b = (uint8_t)(((b & 0xcc) >> 2) | ((b & 0x33) << 2));
  b = (uint8_t)(((b & 0xaa) >> 1) | ((b & 0x55) << 1));
  return b;
}

static void raw_reverse(sox_format_t ft, uint8_t *buf, size_t n)
{
  size_t i;

  if (ft->encoding.reverse_bits == SOX_OPTION_YES)
    for (i = 0; i < n; ++i)
      buf[i] = raw_bitrev(buf[i]);
  if (ft->encoding.reverse_nibbles == SOX_OPTION_YES)
    for (i = 0; i < n; ++i)
      buf[i] = (uint8_t)((buf[i] >> 4) | (buf[i] << 4));
}

static size_t raw_read_bytes(sox_format_t ft, uint8_t *buf, size_t n)
{
  size_t got = lsx_readbuf(ft, buf, n);
  raw_reverse(ft, buf, got);
  return got;
}

static size_t raw_write_bytes(sox_format_t ft, uint8_t *buf, size_t n)
{
  raw_reverse(ft, buf, n);
  return lsx_writebuf(ft, buf, n);
}

/*-------------------------------- Reading ---------------------------------*/

#define RAW_BLOCK 1024

typedef union {
  uint8_t  b[RAW_BLOCK];
  uint16_t w[RAW_BLOCK];
  uint32_t dw[RAW_BLOCK];
  float    f[RAW_BLOCK];
  double   d[RAW_BLOCK];
} raw_block_t;

#define RAW_READ_LOOP(read_n, conv) do { \
    got = read_n; \
    for (i = 0; i < got; ++i) \
      buf[i] = conv; \
  } while (0)

size_t lsx_rawread(sox_format_t ft, sox_sample_t *buf, size_t len)
{
  raw_kind_t kind = raw_kind(ft);
  size_t done = 0;
  raw_block_t t;

  if (kind == raw_bad) {
    raw_bad_size(ft);
    return 0;
  }

  while (done < len) {
    size_t n = min(len - done, (size_t)RAW_BLOCK), got = 0, i;

    switch (kind) {
      case raw_s8:
        RAW_READ_LOOP(raw_read_bytes(ft, t.b, n),
            SOX_SIGNED_8BIT_TO_SAMPLE((int8_t)t.b[i], ft->clips));
        break;
      case raw_u8:
        RAW_READ_LOOP(raw_read_bytes(ft, t.b, n),
            SOX_UNSIGNED_8BIT_TO_SAMPLE(t.b[i], ft->clips));
        break;
      case raw_ulaw:
        RAW_READ_LOOP(raw_read_bytes(ft, t.b, n),
            lsx_ulaw2linear_table[t.b[i]]);
        break;
      case raw_alaw:
        RAW_READ_LOOP(raw_read_bytes(ft, t.b, n),
            lsx_alaw2linear_table[t.b[i]]);
        break;
      case raw_s16:
        RAW_READ_LOOP(lsx_read_w_buf(ft, t.w, n),
            SOX_SIGNED_16BIT_TO_SAMPLE((int16_t)t.w[i], ft->clips));
        break;
      case raw_u16:
        RAW_READ_LOOP(lsx_read_w_buf(ft, t.w, n),
            SOX_UNSIGNED_16BIT_TO_SAMPLE(t.w[i], ft->clips));
        break;
      case raw_s24:
        RAW_READ_LOOP(lsx_read_3_buf(ft, t.dw, n),
            SOX_SIGNED_24BIT_TO_SAMPLE((sox_sample_t)(t.dw[i] << 8) >> 8,
                                       ft->clips));
        break;
      case raw_u24:
        RAW_READ_LOOP(lsx_read_3_buf(ft, t.dw, n),
            SOX_UNSIGNED_24BIT_TO_SAMPLE(t.dw[i], ft->clips));
        break;
      case raw_s32:
        RAW_READ_LOOP(lsx_read_dw_buf(ft, t.dw, n),
            SOX_SIGNED_32BIT_TO_SAMPLE((int32_t)t.dw[i], ft->clips));
        break;
      case raw_u32:
        RAW_READ_LOOP(lsx_read_dw_buf(ft, t.dw, n),
            SOX_UNSIGNED_32BIT_TO_SAMPLE(t.dw[i], ft->clips));
        break;
      case raw_f32:
        RAW_READ_LOOP(lsx_read_f_buf(ft, t.f, n),
            SOX_FLOAT_32BIT_TO_SAMPLE(t.f[i], ft->clips));
        break;
      case raw_f64:
        RAW_READ_LOOP(lsx_read_df_buf(ft, t.d, n),
            SOX_FLOAT_64BIT_TO_SAMPLE(t.d[i], ft->clips));
        break;
      default:
        return done;
    }
    buf += got;
    done += got;
    if (got < n)
      break;
  }
  return done;
}

/*-------------------------------- Writing ---------------------------------*/

#define RAW_WRITE_LOOP(conv, write_n) do { \
    for (i = 0; i < n; ++i) \
      conv; \
    put = write_n; \
  } while (0)

size_t lsx_rawwrite(sox_format_t ft, sox_sample_t const *buf, size_t len)
{
  raw_kind_t kind = raw_kind(ft);
  size_t done = 0;
  raw_block_t t;

  if (kind == raw_bad) {
    raw_bad_size(ft);
    return 0;
  }

  while (done < len) {
    size_t n = min(len - done, (size_t)RAW_BLOCK), put = 0, i;

    switch (kind) {
      case raw_s8:
        RAW_WRITE_LOOP(t.b[i] = (uint8_t)SOX_SAMPLE_TO_SIGNED_8BIT(buf[i], ft->clips),
            raw_write_bytes(ft, t.b, n));
        break;
      case raw_u8:
        RAW_WRITE_LOOP(t.b[i] = SOX_SAMPLE_TO_UNSIGNED_8BIT(buf[i], ft->clips),
            raw_write_bytes(ft, t.b, n));
        break;
      case raw_ulaw:
        RAW_WRITE_LOOP(t.b[i] = lsx_14linear2ulaw(
              (int16_t)SOX_SAMPLE_TO_SIGNED(14, buf[i], ft->clips)),
            raw_write_bytes(ft, t.b, n));
        break;
      case raw_alaw:
        RAW_WRITE_LOOP(t.b[i] = lsx_13linear2alaw(
              (int16_t)SOX_SAMPLE_TO_SIGNED(13, buf[i], ft->clips)),
            raw_write_bytes(ft, t.b, n));
        break;
      case raw_s16:
        RAW_WRITE_LOOP(t.w[i] = (uint16_t)SOX_SAMPLE_TO_SIGNED_16BIT(buf[i], ft->clips),
            lsx_write_w_buf(ft, t.w, n));
        break;
      case raw_u16:
        RAW_WRITE_LOOP(t.w[i] = SOX_SAMPLE_TO_UNSIGNED_16BIT(buf[i], ft->clips),
            lsx_write_w_buf(ft, t.w, n));
        break;
      case raw_s24:
        RAW_WRITE_LOOP(t.dw[i] = (uint32_t)SOX_SAMPLE_TO_SIGNED_24BIT(buf[i], ft->clips)
              & 0xffffffUL,
            lsx_write_3_buf(ft, t.dw, n));
        break;
      case raw_u24:
        RAW_WRITE_LOOP(t.dw[i] = SOX_SAMPLE_TO_UNSIGNED_24BIT(buf[i], ft->clips)
              & 0xffffffUL,
            lsx_write_3_buf(ft, t.dw, n));
        break;
      case raw_s32:
        RAW_WRITE_LOOP(t.dw[i] = (uint32_t)SOX_SAMPLE_TO_SIGNED_32BIT(buf[i], ft->clips),
            lsx_write_dw_buf(ft, t.dw, n));
        break;
      case raw_u32:
        RAW_WRITE_LOOP(t.dw[i] = SOX_SAMPLE_TO_UNSIGNED_32BIT(buf[i], ft->clips),
            lsx_write_dw_buf(ft, t.dw, n));
        break;
      case raw_f32:
        RAW_WRITE_LOOP(t.f[i] = SOX_SAMPLE_TO_FLOAT_32BIT(buf[i], ft->clips),
            lsx_write_f_buf(ft, t.f, n));
        break;
      case raw_f64:
        RAW_WRITE_LOOP(t.d[i] = SOX_SAMPLE_TO_FLOAT_64BIT(buf[i], ft->clips),
            lsx_write_df_buf(ft, t.d, n));
        break;
      default:
        return done;
    }
    buf += put;
    done += put;
    if (put < n)
      break;
  }
  return done;
}

/*----------------------------- Start and stop -----------------------------*/

/* filesize (in bytes) -> total samples, rounding towards zero. */
static uint64_t raw_length(uint64_t bytes, unsigned bits)
{
  return bits ? bytes * 8 / bits : 0;
}

int lsx_rawstartread(sox_format_t ft)
{
  off_t here = lsx_tell(ft);

  ft->data_start = here > 0 ? (uint64_t)here : 0;

  if (ft->mode == 'r' && ft->signal.length == SOX_UNSPEC && !ft->ignore_length) {
    uint64_t bytes = lsx_filelength(ft);
    if (bytes > ft->data_start)
      ft->signal.length =
          raw_length(bytes - ft->data_start, ft->encoding.bits_per_sample);
  }
  return SOX_SUCCESS;
}

int lsx_rawstartwrite(sox_format_t ft)
{
  off_t here = lsx_tell(ft);

  ft->data_start = here > 0 ? (uint64_t)here : 0;
  return SOX_SUCCESS;
}

int lsx_rawstopread(sox_format_t ft)
{
  (void)ft;
  return SOX_SUCCESS;
}

int lsx_rawstopwrite(sox_format_t ft)
{
  (void)ft;
  return SOX_SUCCESS;
}

int lsx_rawseek(sox_format_t ft, uint64_t offset)
{
  switch (raw_kind(ft)) {
    case raw_bad:
      raw_bad_size(ft);
      return SOX_EOF;
    default:
      return lsx_offset_seek(ft, (off_t)ft->data_start, offset);
  }
}

int lsx_rawstart(sox_format_t ft, sox_bool default_rate,
                 sox_bool default_channels, sox_bool default_length,
                 sox_encoding_t encoding, unsigned bits_per_sample)
{
  if (default_rate && ft->signal.rate == 0) {
    raw_warn("`%s': sample rate not specified; trying %gkHz", ft->filename, 8.);
    ft->signal.rate = 8000;
  }
  if (default_channels && ft->signal.channels == 0) {
    raw_warn("`%s': # channels not specified; trying mono", ft->filename);
    ft->signal.channels = 1;
  }
  if (encoding != SOX_ENCODING_UNKNOWN) {
    if (ft->mode == 'r' && ft->encoding.encoding != SOX_ENCODING_UNKNOWN &&
        ft->encoding.encoding != encoding)
      raw_report("`%s': Format options overriding file-type encoding",
                 ft->filename);
    else
      ft->encoding.encoding = encoding;
  }
  if (bits_per_sample != 0) {
    if (ft->mode == 'r' && ft->encoding.bits_per_sample != 0 &&
        ft->encoding.bits_per_sample != bits_per_sample)
      raw_report("`%s': Format options overriding file-type sample-size",
                 ft->filename);
    else
      ft->encoding.bits_per_sample = bits_per_sample;
  }
  return ft->mode == 'r' ?
      (default_length ? lsx_rawstartread(ft) : SOX_SUCCESS) :
      lsx_rawstartwrite(ft);
}

/*------------------------------ `raw' handler ------------------------------*/

static int raw_startread(sox_format_t ft)
{
  return lsx_rawstart(ft, sox_false, sox_false, sox_true,
                      SOX_ENCODING_UNKNOWN, 0);
}

static int raw_startwrite(sox_format_t ft)
{
  return lsx_rawstart(ft, sox_false, sox_false, sox_false,
                      SOX_ENCODING_UNKNOWN, 0);
}

sox_format_handler_t const *lsx_raw_format_fn(void)
{
  static char const *const names[] = {"raw", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_SIGN2, 32, 24, 16, 8, 0,
    SOX_ENCODING_UNSIGNED, 32, 24, 16, 8, 0,
    SOX_ENCODING_ULAW, 8, 0,
    SOX_ENCODING_ALAW, 8, 0,
    SOX_ENCODING_FLOAT, 64, 32, 0,
    0};
  static sox_format_handler_t const handler = {
    .names = names,
    .flags = 0,
    .startread = raw_startread,
    .read = lsx_rawread,
    .stopread = lsx_rawstopread,
    .startwrite = raw_startwrite,
    .write = lsx_rawwrite,
    .stopwrite = lsx_rawstopwrite,
    .seek = lsx_rawseek,
    .write_formats = write_encodings,
    .write_rates = NULL,
    .priv_size = 0,
    .description = "Raw PCM, mu-law, or A-law"
  };
  return &handler;
}

