/* Forward declaration so that the handler's function-pointer prototypes below
 * refer to the same `struct sox_format' as the definition further down. */
struct sox_format;

typedef struct {
  char const * const *names;

input.command:
gen() {
  mod=$1; names=$2; enc=$3; bits=$4; flags=$5
  cat > "fmt_$mod.c" << EOF
/* Raw (headerless) $mod audio.  Original work; a thin wrapper around the
 * shared raw sample coding in fmt_raw.c. */
#include "sox_i.h"

static int start(sox_format_t ft)
{
  return lsx_rawstart(ft, sox_true, sox_true, sox_true,
                      SOX_ENCODING_$enc, $bits);
}

sox_format_handler_t const *lsx_${mod}_format_fn(void)
{
  static char const *const names[] = {$names, NULL};
  static unsigned const write_encodings[] = {SOX_ENCODING_$enc, $bits, 0, 0};
  static sox_format_handler_t const handler = {
    .names          = names,
    .flags          = $flags,
    .startread      = start,
    .read           = lsx_rawread,
    .stopread       = lsx_rawstopread,
    .startwrite     = start,
    .write          = lsx_rawwrite,
    .stopwrite      = lsx_rawstopwrite,
    .seek           = lsx_rawseek,
    .write_formats  = write_encodings,
    .write_rates    = NULL,
    .priv_size      = 0,
    .description    = "Raw audio"
  };
  return &handler;
}
