/* Raw (headerless) inverse-bit-order $desc.  Original work; a thin wrapper
 * around the shared raw sample coding in fmt_raw.c.
 *
 * The reference always reports \`Reverse Bits: yes' for this format -- even
 * when -X is also given -- so the option is forced on here as well as being
 * advertised through SOX_FILE_BIT_REV. */
#include "sox_i.h"

static int start(sox_format_t ft)
{
  ft->encoding.reverse_bits = SOX_OPTION_YES;
  return lsx_rawstart(ft, sox_true, sox_true, sox_true,
                      SOX_ENCODING_$enc, 8);
}

sox_format_handler_t const *lsx_${mod}_format_fn(void)
{
