input.content:
/* Asterisk PBX `signed linear' headerless format: mono, 8kHz, 16-bit signed,
 * little-endian.  Original work.
 *
 * Unlike the other headerless formats the reference does not work out a length
 * (and hence a duration) for an .sln file, so this handler deliberately does
 * not call lsx_rawstartread on the way in. */
#include "sox_i.h"

static int start_read(sox_format_t ft)
{
  int rc = lsx_check_read_params(ft, 1, 8000., SOX_ENCODING_SIGN2, 16,
                                 (uint64_t)0, sox_false);

  ft->data_start = 0;  /* headerless: audio starts at the beginning */
  return rc;
}

sox_format_handler_t const *lsx_sln_format_fn(void)
{
  static char const *const names[] = {"sln", NULL};
  static unsigned const write_encodings[] = {SOX_ENCODING_SIGN2, 16, 0, 0};
  static double const write_rates[] = {8000, 0};
  static sox_format_handler_t const handler = {
    .names          = names,
    .flags          = SOX_FILE_LIT_END | SOX_FILE_MONO,
    .startread      = start_read,
    .read           = lsx_rawread,
    .stopread       = lsx_rawstopread,
    .startwrite     = lsx_rawstartwrite,
    .write          = lsx_rawwrite,
    .stopwrite      = lsx_rawstopwrite,
    .seek           = lsx_rawseek,
    .write_formats  = write_encodings,
    .write_rates    = write_rates,
    .priv_size      = 0,
    .description    = "Asterisk PBX headerless format"
  };
  return &handler;
}

